package ru.secondmemory;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.media.*;
import android.os.*;
import android.widget.*;
import java.util.*;

public class VoiceSetupActivity extends Activity {
 private TextView status,speechStatus;private Button enroll;private Switch enabled;private volatile boolean cancelled;private final Handler main=new Handler(Looper.getMainLooper());
 public void onCreate(Bundle b){super.onCreate(b);ScrollView scroll=new ScrollView(this);LinearLayout p=Ui.column(this);scroll.addView(p);setContentView(scroll);ScreenLayout.apply(this,p);Ui.title(p,"Твой голос","Одна настройка для голосовых команд");
  LinearLayout profile=Ui.card(p);status=Ui.label(this,"",16);profile.addView(status);enroll=Ui.button(profile,"Записать мой голос — 15 секунд",true,this::start);
  enabled=new Switch(this);enabled.setText("Голосовые команды");enabled.setChecked(getSharedPreferences("voice",0).getBoolean("enabled",false));profile.addView(enabled);enabled.setOnCheckedChangeListener((v,on)->{getSharedPreferences("voice",0).edit().putBoolean("enabled",on).apply();show();});
  LinearLayout speech=Ui.card(p);speech.addView(Ui.text(this,"Озвучивание ответов",19,Ui.INK));speechStatus=Ui.label(this,"",14);speech.addView(speechStatus);Ui.button(speech,"Проверить озвучивание",false,()->{VoiceOutput.retry(this);VoiceOutput.speak(this,"Голос помощника работает. Обратись ко мне: Помощник, что делать?");main.postDelayed(this::show,2000);});Ui.button(speech,"Настройки русского голоса Android",false,()->{try{startActivity(new Intent("com.android.settings.TTS_SETTINGS"));}catch(ActivityNotFoundException e){Toast.makeText(this,"Открой в настройках телефона «Синтез речи»",Toast.LENGTH_LONG).show();}});
  LinearLayout help=Ui.card(p);help.addView(Ui.text(this,"Как записать образец",19,Ui.INK));help.addView(Ui.label(this,"Нажми кнопку и говори 15 секунд обычным голосом. Можно рассказать о планах на день — зачитывать специальный текст не нужно. Выбери тихое место без других голосов. На время настройки останови основную запись.",15));help.addView(Ui.label(this,"После настройки включи запись на главном экране и обращайся «Помощник». Все разговоры сохраняются; голос владельца проверяется для команд. В шуме возможны ошибки, проверка не защищает от воспроизведения записи голоса.",14));Ui.button(p,"Назад",false,this::finish);VoiceOutput.init(this);show();main.postDelayed(this::show,1000);
 }
 private void show(){if(status!=null&&enroll.isEnabled())status.setText((OwnerVoice.enrolled(this)?"✓ Образец голоса сохранён":"Образец голоса ещё не записан")+"\nКоманды: "+(getSharedPreferences("voice",0).getBoolean("enabled",false)?"включены":"выключены")+"\n"+getSharedPreferences("voice",0).getString("last_error",""));if(speechStatus!=null)speechStatus.setText(VoiceOutput.status);}
 private void start(){if(RecorderService.running||RecorderService.stopping){status.setText("Останови запись на главном экране на время настройки голоса");return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},1);return;}enroll.setEnabled(false);cancelled=false;new Thread(()->{AudioRecord mic=null;try(OwnerVoice voice=new OwnerVoice(this)){
   int size=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);mic=new AudioRecord(MediaRecorder.AudioSource.VOICE_RECOGNITION,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(32000,size*2));if(mic.getState()!=AudioRecord.STATE_INITIALIZED)throw new Exception("Микрофон недоступен");short[] all=new short[16000*15];mic.startRecording();int n=0;while(n<all.length&&!cancelled){int r=mic.read(all,n,Math.min(1600,all.length-n));if(r<0)throw new Exception("Ошибка микрофона");n+=r;final int left=15-n/16000;main.post(()->status.setText("Говори обычным голосом. Осталось "+left+" сек."));}mic.stop();if(cancelled)return;float[][] vectors=new float[3][];for(int k=0;k<3;k++){float[] pcm=new float[80000];double energy=0;for(int i=0;i<pcm.length;i++){pcm[i]=all[k*80000+i]/32768f;energy+=pcm[i]*pcm[i];}if(Math.sqrt(energy/pcm.length)<.005)throw new Exception("Голос слишком тихий. Поднеси телефон ближе и повтори");vectors[k]=voice.embedding(pcm);}if(OwnerVoice.cosine(vectors[0],vectors[1])<.5||OwnerVoice.cosine(vectors[0],vectors[2])<.5)throw new Exception("Образцы не совпали. Повтори без других голосов рядом");float[] avg=new float[vectors[0].length];for(float[] v:vectors){double norm=0;for(float f:v)norm+=f*f;norm=Math.sqrt(norm);for(int i=0;i<v.length;i++)avg[i]+=v[i]/norm;}OwnerVoice.save(this,avg);getSharedPreferences("voice",0).edit().remove("last_error").apply();main.post(()->{enabled.setChecked(true);show();VoiceOutput.speak(this,"Голос запомнила. Включи запись и скажи: Помощник, что делать?");});
  }catch(Exception|LinkageError e){final String msg="Не удалось: "+e.getMessage();getSharedPreferences("voice",0).edit().putString("last_error",msg).apply();main.post(()->status.setText(msg));}finally{if(mic!=null){try{mic.stop();}catch(Exception ignored){}mic.release();}main.post(()->{enroll.setEnabled(true);show();});}},"voice-enroll").start();}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==1&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)start();}
 protected void onDestroy(){cancelled=true;super.onDestroy();}
}
